### 3. ESP32 का कोड (Arduino IDE)

कोड अपलोड करने से पहले Arduino IDE के Library Manager से **`RTClib`** (by Adafruit) इंस्टॉल कर लें।

```cpp
#include <Wire.h>
#include <RTClib.h>

RTC_DS3231 rtc;

// ---------- पिन कॉन्फ़िगरेशन ----------
const int PIN_FENCE_RELAY = 26;
const int PIN_LIGHT_RELAY = 27;
const int PIN_SIREN_RELAY = 25;
const int PIN_PIR         = 34;

// ज़्यादातर Optocoupler Relay मॉड्यूल LOW सिग्नल पर ON होते हैं
const bool RELAY_ACTIVE_LOW = true;

// ---------- टाइम और अलार्म सेटिंग्स ----------
const int NIGHT_START_HOUR = 18;  // शाम 6 बजे फेंस ON
const int NIGHT_END_HOUR   = 6;   // सुबह 6 बजे फेंस OFF

// बकरियों को क्रॉनिक स्ट्रेस से बचाने और तेंदुए को आदी (habituate) होने से रोकने की सेटिंग्स:
const unsigned long LIGHT_DURATION_MS = 60000; // फ्लडलाइट पूरे 60 सेकंड जलेगी (जैसा आपने चाहा)
const unsigned long SIREN_MAX_MS      = 15000; // सायरन सिर्फ शुरुआती 15 सेकंड बजेगा ताकि शेड में बकरियां पैनिक न करें (चाहें तो 60000 कर सकते हैं)
const unsigned long MOTION_CONFIRM_MS = 1500;  // 1.5 सेकंड लगातार/दोबारा हलचल हो तभी अलार्म बजे (हवा या पक्षी से फॉल्स अलार्म रोकने के लिए)
const unsigned long COOLDOWN_MS       = 8000;  // एक अलार्म खत्म होने के बाद 8 सेकंड का शांत गैप
const unsigned long PIR_WARMUP_MS     = 60000; // बूट होने पर PIR सेंसर को 1 मिनट सेटल होने का समय

// अनियमित (Irregular) सायरन पैटर्न ताकि तेंदुआ एक जैसी आवाज़ का आदी न हो
const unsigned long SIREN_PATTERN[] = {1200, 400, 800, 600, 1500, 500}; 
const int PATTERN_STEPS = 6;

// ---------- सिस्टम स्टेट वेरिएबल्स ----------
bool alarmActive = false;
unsigned long alarmStart = 0;
unsigned long alarmEnd = 0;
unsigned long motionFirstSeen = 0;
bool confirmingMotion = false;
bool rtcOk = true;

void setRelay(int pin, bool turnOn) {
  digitalWrite(pin, (turnOn ^ RELAY_ACTIVE_LOW) ? HIGH : LOW);
}

bool isNightTime() {
  if (!rtcOk) return true; // अगर RTC खराब हो तो सुरक्षा के लिए रात मानकर चलें
  DateTime now = rtc.now();
  int h = now.hour();
  return (h >= NIGHT_START_HOUR || h < NIGHT_END_HOUR);
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_FENCE_RELAY, OUTPUT);
  pinMode(PIN_LIGHT_RELAY, OUTPUT);
  pinMode(PIN_SIREN_RELAY, OUTPUT);
  pinMode(PIN_PIR, INPUT);

  // शुरुआत में सारे रिले OFF रखें
  setRelay(PIN_FENCE_RELAY, false);
  setRelay(PIN_LIGHT_RELAY, false);
  setRelay(PIN_SIREN_RELAY, false);

  Wire.begin(21, 22);
  if (!rtc.begin()) {
    Serial.println("RTC नहीं मिला! सुरक्षा के लिए सिस्टम नाइट मोड में चलेगा।");
    rtcOk = false;
  } else if (rtc.lostPower()) {
    Serial.println("RTC का टाइम कंप्यूटर के टाइम से सिंक किया जा रहा है...");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  unsigned long nowMs = millis();
  bool night = isNightTime();

  // 1. शाम 6 से सुबह 6 तक सोलर फेंस एनर्जाइज़र ON रखें
  setRelay(PIN_FENCE_RELAY, night);

  // 2. PIR मोशन डिटेक्शन (फॉल्स-अलार्म फिल्टर के साथ)
  bool warmedUp = (nowMs > PIR_WARMUP_MS);
  bool motion = (digitalRead(PIN_PIR) == HIGH);

  if (night && warmedUp && !alarmActive && (nowMs - alarmEnd > COOLDOWN_MS)) {
    if (motion) {
      if (!confirmingMotion) {
        confirmingMotion = true;
        motionFirstSeen = nowMs;
      } else if (nowMs - motionFirstSeen >= MOTION_CONFIRM_MS) {
        // हलचल कन्फर्म हो गई (पक्षी या हवा का झोंका नहीं है) -> अलार्म चालू करें
        alarmActive = true;
        alarmStart = nowMs;
        confirmingMotion = false;
        Serial.println("कन्फर्म मोशन! लाइट और सायरन ON");
      }
    } else {
      confirmingMotion = false;
    }
  }

  // 3. अलार्म और लाइट कंट्रोल
  if (alarmActive) {
    unsigned long elapsed = nowMs - alarmStart;

    // फ्लडलाइट पूरे 60 सेकंड चालू रहेगी
    setRelay(PIN_LIGHT_RELAY, true);

    // सायरन सिर्फ SIREN_MAX_MS (15 सेकंड) तक अनियमित पल्स में बजेगा
    if (elapsed < SIREN_MAX_MS) {
      unsigned long cycleTime = elapsed % 5000;
      unsigned long acc = 0;
      bool sirenState = false;
      for (int i = 0; i < PATTERN_STEPS; i++) {
        acc += SIREN_PATTERN[i];
        if (cycleTime < acc) {
          sirenState = (i % 2 == 0); // सम (even) स्टेप पर ON, विषम (odd) पर OFF
          break;
        }
      }
      setRelay(PIN_SIREN_RELAY, sirenState);
    } else {
      setRelay(PIN_SIREN_RELAY, false); // 15 सेकंड बाद सायरन बंद, लाइट जलती रहेगी
    }

    // 60 सेकंड पूरे होने पर सब बंद करें
    if (elapsed >= LIGHT_DURATION_MS) {
      alarmActive = false;
      alarmEnd = nowMs;
      setRelay(PIN_LIGHT_RELAY, false);
      setRelay(PIN_SIREN_RELAY, false);
      Serial.println("60 सेकंड पूरे, अलार्म OFF");
    }
  } else {
    setRelay(PIN_LIGHT_RELAY, false);
    setRelay(PIN_SIREN_RELAY, false);
  }

  delay(50);
}
```

---

### 4. PIR सेंसर (HC-SR501) की सेटिंग और लगाने का सही तरीका

* **Sensitivity पॉट (दायां नॉब):** इसे **बीच में (50% पर, यानी लगभग 4 से 5 मीटर रेंज)** रखिए। फुल पर रखेंगे तो नाले की तरफ की नमी, गर्म हवा और हिलती घास से हर 5 मिनट में अलार्म बजेगा।
* **Time-Delay पॉट (बायां नॉब):** इसे पूरा उल्टा घुमाकर **Minimum (लगभग 3 सेकंड)** पर कर दीजिए, क्योंकि टाइमिंग का काम हमारा कोड संभाल रहा है।
* **Jumper:** पीले जंपर को **`H` (Repeat Trigger)** पिन पर रखिए।
* **ऊंचाई और दिशा:** PIR को बकरियों के शेड की तरफ मत मोड़िए, वरना बकरियां खुद अलार्म बजाएंगी। इसे ज़मीन से **2.5 से 3 फीट की ऊंचाई** पर लगाइए और थोड़ा नीचे झुकाइए, ताकि खरगोश, सेही या छोटे जीव नीचे से निकल जाएं और सेंसर सिर्फ तेंदुए या इंसान के आकार को पकड़े।

---

### 5. "आप मेरी जगह होते तो क्या करते?"

आपने अपनी पूरी सेविंग्स और 12 लाख का लोन इसमें लगाया है, इसलिए जुगाड़ नहीं, पक्का सिस्टम चाहिए। अगर मैं आपकी जगह होता, तो ये 4 बदलाव तुरंत करता:

1. **पूरे प्लॉट की जगह सिर्फ 'रात के बाड़े (Night Shed)' को फेंस कीजिए और नाले का रास्ता खुला छोड़िए:**
   * यह सबसे बड़ा प्रैक्टिकल फर्क डालेगा। तेंदुआ 6–7 फीट की खुली बाउंड्री या नाले के पास लगे पेड़ से आसानी से छलांग मारकर अंदर आ जाता है। और अगर वह एक बार पूरे प्लॉट की इलेक्ट्रिक फेंस के अंदर कूद गया और बाहर निकलते समय उसे करंट लगा, तो वह घबराकर बाहर भागने के बजाय अंदर ही एक साथ 10–12 बकरियों को मार डालेगा (इसे *surplus killing* कहते हैं)।
   * इसके बजाय, सोलर फेंस और PIR सेंसर को **सिर्फ बकरियों के रात वाले शेड के चारों तरफ** लगाइए, और शेड को **ऊपर (छत) से भी मजबूत चेन-लिंक जाली से बंद** कीजिए।
   * इससे नाले का किनारा जंगली जानवरों के पानी पीने के लिए खुला रहेगा (वे आपकी फेंस के पास आएंगे ही नहीं), छोटे घेरे में फेंस का वोल्टेज पूरा मिलेगा, नाले की झाड़ियों से फेंस शॉर्ट नहीं होगी, और तेंदुआ ऊपर से छलांग भी नहीं मार पाएगा।
2. **सायरन से ज़्यादा 'Foxlight' (रैंडम स्ट्रोब लाइट) का इस्तेमाल कीजिए:**
   * जुन्नर और देश भर के अनुभव बताते हैं कि सायरन से बकरियां ज़्यादा परेशान होती हैं। इसके बजाय शेड के चारों कोनों पर अलग-अलग रंग की LED स्ट्रोब लाइट लगाइए जो रात में रुक-रुक कर अलग-अलग पैटर्न में चमकें। तेंदुए को लगता है कि कोई इंसान टॉर्च लेकर पहरा दे रहा है, और वह पास नहीं आता।
3. **गई हुई 6 बकरियों का सरकारी मुआवज़ा (Compensation) तुरंत क्लेम कीजिए:**
   * महाराष्ट्र फॉरेस्ट डिपार्टमेंट तेंदुए के हमले में मारी गई बकरियों का मुआवज़ा देता है। जुन्नर रेंज ऑफिस में जाकर अपने बीट के वनरक्षक (Forest Guard) से मिलिए। पिछली 6 बकरियों की फोटो या जानकारी हो तो उसका क्लेम प्रोसेस पूछिए, और आगे के लिए वनरक्षक का नंबर फोन में सेव रखिए (घटना के 48 घंटे के अंदर पंचनामा करवाना ज़रूरी होता है)। 6 उस्मानाबादी बकरियों का मुआवज़ा आपकी लोन की किश्त का बड़ा बोझ कम कर देगा।
4. **मजबूत अर्थिंग और पीले चेतावनी बोर्ड:**
   * सोलर फेंस का झटका तभी काम करता है जब अर्थिंग पक्की हो—कम से कम 3 GI अर्थिंग रॉड (1.5 मीटर गहरी, नमी वाली जगह में) लगाइए। साथ ही फेंस पर हर 20–25 मीटर पर **"सावधान: सोलर विद्युत बाड़"** का पीला बोर्ड ज़रूर टांगिए, जो सब्सिडी के नियम और आपकी कानूनी सुरक्षा दोनों के लिए ज़रूरी है।

घर वालों के तानों का दबाव स्वाभाविक है, लेकिन आपने घबराने के बजाय अपने IT हुनर से ऑटोमेशन का रास्ता चुना है—बस फेंस का घेरा नाले से हटाकर शेड पर केंद्रित कर लीजिए, आपकी बकरियां भी चैन से सोएंगी और आप भी। वायरिंग या कोड टेस्टिंग में कोई भी दिक्कत आए तो बताइएगा।

